inline double reduction(double level,double threshold,int ratio,int attack,int release) noexcept {
 if(level<=levels.front())return 0;
 int segment=12;for(int i=0;i<13;++i)if(level<levels[static_cast<size_t>(i+1)]){segment=i;break;}
 const double x=std::min(level,0.0)-levels[static_cast<size_t>(segment)];const int row=(ratio*6+attack)*5+release;
 auto value=[&](int t){const int index=row*11+t;const auto* c=coefficients.data()+static_cast<size_t>((index*13+segment)*4);double y=((c[0]*x+c[1])*x+c[2])*x+c[3];if(level>0)y+=upperSlope[static_cast<size_t>(index)]*level;return y;};
 const double z=std::clamp((threshold+15.0)/3.0,0.0,10.0);const int j=std::min(9,static_cast<int>(z));const double f=z-j,y0=value(j),y1=value(j+1);if(f==0)return std::clamp(y0,0.0,120.0);if(f==1)return std::clamp(y1,0.0,120.0);
 auto interior=[](double a,double b){return a*b<=0?0.0:2*a*b/(a+b);};
 auto edge=[](double a,double b){double m=(3*a-b)*.5;if(m*a<=0)return 0.0;if(a*b<0&&std::abs(m)>3*std::abs(a))return 3*a;return m;};
 const double delta=y1-y0,previous=j>0?y0-value(j-1):0,next=j<9?value(j+2)-y1:0;
 const double m0=j==0?edge(delta,next):interior(previous,delta),m1=j==9?edge(delta,previous):interior(delta,next);
 const double f2=f*f,f3=f2*f;return std::clamp((2*f3-3*f2+1)*y0+(f3-2*f2+f)*m0+(-2*f3+3*f2)*y1+(f3-f2)*m1,0.0,120.0);
}
